function notice(message,error=false){const n=document.querySelector('#notice');n.textContent=message;n.className=error?'error':'';n.style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.style.display='none',6000);}
async function api(url,method='GET',body){const r=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-DNCH-Request':'1',...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await r.json();if(!r.ok){const e=new Error(t(result.error)||t('error'));e.code=result.error;e.status=r.status;throw e;}return result;}
const tag=s=>`<span class="tag ${esc(s)}">${esc(t(s))}</span>`;
const btn=(label,action,data='',klass='secondary')=>`<button class="${klass}" data-action="${esc(action)}" ${data}>${esc(t(label))}</button>`;
const selectOptions=(items,value)=>items.map(x=>{const [v,label]=Array.isArray(x)?x:[x,t(x)];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`;}).join('');
function field(name,value='',options={}){const {type='text',required=true,items,wide=false}=options;return `<label class="field ${wide?'wide':''}"><span>${esc(t(name==='title'?'title_field':name))}${required?' *':''}</span>${items?`<select name="${name}" ${required?'required':''}>${selectOptions(items,value)}</select>`:type==='textarea'?`<textarea name="${name}" ${required?'required':''} maxlength="8000">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any" min="0"':''} ${type==='password'?'minlength="12" maxlength="128" autocomplete="new-password"':''}>`}</label>`;}
function check(name,value=false){return `<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(t(name))}</label>`;}
const empty=()=>`<div class="empty">${esc(t('empty'))}</div>`;
const formActions=(label='save')=>`<div class="actions"><button class="primary" type="submit">${esc(t(label))}</button></div><p class="error-text" role="alert"></p>`;
function modal(html){document.querySelector('#detail-content').innerHTML=html;if(!detail.open)detail.showModal();}
function object(form){const f=new FormData(form),b=Object.fromEntries(f);for(const n of ['weight_kg','volume_m3','loading_m','pallets','price_min','price_max','moq','capacity_m3','capacity_kg','daily_eur'])if(n in b)b[n]=b[n]===''?null:Number(b[n]);for(const n of ['hazardous','synthetic','accept_terms','active','publish_consent'])if(form.elements[n])b[n]=form.elements[n].checked;return b;}
function profileFields(c={}){const p={...c.address,...c.profile,...c};return `<h2>${esc(t('legal'))}</h2><div class="fields">${field('name_native',p.name_native)}${field('name_latin',p.name_latin)}${field('country',p.country||'BG',{items:[['BG','България / Bulgaria / 保加利亚'],['CN','Китай / China / 中国']]})}${field('registration_number',p.registration_number)}${field('legal_form',p.legal_form)}${field('vat_number',p.vat_number,{required:false})}${field('city',p.city)}${field('postal_code',p.postal_code)}${field('street',p.street,{wide:true})}</div><section class="form-section"><h2>${esc(t('contact'))}</h2><div class="fields">${field('contact_name',p.contact_name)}${field('position',p.position)}${field('contact_email',p.contact_email,{type:'email'})}${field('phone',p.phone,{type:'tel'})}${field('wechat',p.wechat,{required:false})}${field('sector',p.sector||'Technology',{items:state.env.taxonomy.sectors})}${field('activity',p.activity||'Manufacturer',{items:state.env.taxonomy.activities})}${field('employees',p.employees||'1-5',{items:['1-5','5-20','20-50','50-200','200+']})}${field('website',p.website,{type:'url',required:false})}${field('partners',p.partners,{required:false})}${field('description',p.description,{type:'textarea',wide:true})}${field('experience',p.experience,{type:'textarea',required:false,wide:true})}${field('chamber_bg',String(p.chamber_bg??''),{items:[['',t('all')],['true',t('yes')],['false',t('no')]]})}${field('chamber_cn',String(p.chamber_cn??''),{items:[['',t('all')],['true',t('yes')],['false',t('no')]]})}<fieldset class="wide"><legend>${esc(t('languages'))} *</legend>${['bg','en','zh'].map(l=>`<label class="check"><input type="checkbox" name="languages" value="${l}" ${(p.languages||['bg','en']).includes(l)?'checked':''}>${{bg:'Български',en:'English',zh:'中文'}[l]}</label>`).join('')}</fieldset></div></section>`;}
function companyBody(form){const b=object(form);b.languages=new FormData(form).getAll('languages');b.chamber_bg=b.chamber_bg==='true'?true:b.chamber_bg==='false'?false:null;b.chamber_cn=b.chamber_cn==='true'?true:b.chamber_cn==='false'?false:null;return b;}
function layout(){const area=state.env.area,admin=state.user?.system_role==='administrator';const nav=admin?['overview','admin','brokers_admin','audit','security']:area==='hub'?['overview','profile','team','verification','directory','security']:area==='trade'?['overview','listings',...(state.user?['mine','inquiries','documents','security']:[])]:['overview','cargo','routes','matching','shipments','documents','warehouses','brokers','integrations','security'];
 app.innerHTML=`<header class="top"><a class="brand" href="${state.env.platforms.hub}?lang=${lang}">${area==='hub'?'INTERNATIONAL BUSINESS HUB':area==='trade'?'TRADE · BULGARIA × CHINA':'CASPIAN LOGISTICS'}<small>EUROPE · CENTRAL ASIA · CHINA</small></a><nav>${['hub','trade','caspian'].map(k=>`<a class="${k===area?'active':''}" href="${state.env.platforms[k]}?lang=${lang}">${{hub:'BUSINESS HUB',trade:'TRADE',caspian:'CASPIAN'}[k]}</a>`).join('')}<select id="language" aria-label="Language">${selectOptions([['bg','BG'],['en','EN'],['zh','中文']],lang)}</select></nav></header><div class="environment">${esc(t('test'))}</div><div class="layout"><aside><p class="caption">${esc(t('title'))}</p>${nav.map(n=>btn(n,'nav',`data-nav="${n}"`,state.nav===n?'active':'')).join('')}<div class="session">${state.user?`<strong>${esc(state.user.display_name)}</strong><p>${esc(state.user.email)}<br>${esc(t(state.user.role||'admin'))}</p>${tag(state.user.company_status||'active')}${btn('logout','logout')}`:btn('login','auth')}</div></aside><main id="content"><div class="loading">${esc(t('loading'))}</div><footer>INTERNATIONAL BUSINESS HUB · TRADE · CASPIAN LOGISTICS</footer></main></div>`;
 document.querySelector('#language').onchange=e=>{const form=document.querySelector('#content form');if(form && ['register','login','profile','accept'].includes(form.dataset.form))state.draft={kind:form.dataset.form,body:form.dataset.form==='register'||form.dataset.form==='profile'?companyBody(form):object(form)};lang=e.target.value;localStorage.setItem('dnch_workspace_lang',lang);const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);document.documentElement.lang=lang;render();};
}
async function refreshMe(){const me=await api('/api/auth/me');state.user=me.user;state.csrf=me.csrf;}
async function render(){layout();const content=document.querySelector('#content');try{let html;
 if(!state.user && !(state.env.area==='trade' && state.nav==='listings'))html=authPage();
 else {html=await page();}content.innerHTML=html;
 if(state.draft){const form=content.querySelector(`form[data-form="${state.draft.kind}"]`);if(form){for(const [name,value] of Object.entries(state.draft.body)){const nodes=form.querySelectorAll(`[name="${name}"]`);for(const node of nodes){if(node.type==='checkbox')node.checked=Array.isArray(value)?value.includes(node.value):!!value;else if(node.type!=='file')node.value=String(value??'');}}}state.draft=null;}
 }catch(e){content.innerHTML=`<div class="callout">${esc(words[e.code]?t(e.code):t('error'))}</div>${btn('refresh','refresh')}`;}}
function authPage(){const mode=state.auth;return `<section class="auth"><h1>${esc(t(mode==='accept'?'invitation':mode))}</h1><p class="muted">${esc(t('title'))}</p><div class="tabs">${['login','register','accept'].map(m=>btn(m==='accept'?'invitation':m,'auth-mode',`data-mode="${m}"`,mode===m?'active':'')).join('')}</div><form class="panel" data-form="${mode}">${mode==='register'?profileFields(state.draft?.body||{}):''}<div class="fields">${field('email','',{type:'email'})}${field('password','',{type:'password'})}${mode==='accept'?field('display_name')+field('invitation'):''}</div>${mode==='register'?`<div class="callout">${esc(t('verificationNote'))}<br>${esc(t('emailNote'))}</div><label class="check"><input type="checkbox" required name="accept_terms">${esc(t('terms'))}</label>`:''}${formActions(mode==='login'?'login':mode==='register'?'register':'save')}</form>${state.env.area==='trade'?btn('listings','nav','data-nav="listings"'):''}</section>`;}
function metrics(d){return (state.user.system_role==='administrator'?d.companies.map(c=>`<div class="metric"><strong>${c.total}</strong><span>${esc(t(c.status))}</span></div>`):[]).join('')+['listings','inquiries','cargo','shipments'].map(k=>`<div class="metric"><strong>${d[k]||0}</strong><span>${esc(t(k))}</span></div>`).join('');}
async function page(){const n=state.nav;const heading=`<div class="heading"><div><h1>${esc(t(n))}</h1><p class="muted">${esc(t('title'))}</p></div></div>`;
 if(n==='overview'){const d=await api('/api/dashboard');return heading+`${state.user.company_status?`<div class="callout ${state.user.company_status==='verified'?'teal':''}">${tag(state.user.company_status)} ${esc(t('verificationNote'))}</div>`:''}<div class="metrics">${metrics(d)}</div><div class="grid"><article class="panel module"><h2>TRADE</h2><p>${esc(t('directory'))} · ${esc(t('listings'))} · ${esc(t('inquiries'))}</p><a href="${state.env.platforms.trade}?lang=${lang}">TRADE</a></article><article class="panel module teal"><h2>CASPIAN LOGISTICS</h2><p>${esc(t('routes'))} · ${esc(t('matching'))} · ${esc(t('shipments'))}</p><a href="${state.env.platforms.caspian}?lang=${lang}">CASPIAN LOGISTICS</a></article></div>`;}
 if(n==='security')return heading+`<form class="panel" data-form="password"><div class="fields">${field('current_password','',{type:'password'})}${field('new_password','',{type:'password'})}</div>${formActions()}</form>`;
 if(n==='profile'){state.company=await api('/api/company');const c=state.company;return heading+`${tag(c.status)}<p class="muted">${esc(c.review_note)}</p><form class="panel" data-form="profile"><fieldset ${state.user.role!=='owner'?'disabled':''}>${profileFields(c)}${formActions()}</fieldset></form>`;}
 if(n==='team'){const members=await api('/api/company/members');return heading+`<div class="panel"><form data-form="invite"><div class="fields">${field('email','',{type:'email'})}${field('role','viewer',{items:['viewer','trader','dispatcher']})}</div>${formActions('invite')}</form></div><div class="rows">${members.items.map(m=>`<div class="row"><div class="row-top"><div><h3>${esc(m.display_name)}</h3><span class="meta">${esc(m.email)}</span></div>${tag(m.active?'active':'disabled')}</div>${m.role==='owner'?tag('owner'):`<form data-form="member" data-id="${m.id}"><div class="fields">${field('role',m.role,{items:['viewer','trader','dispatcher']})}</div>${check('active',m.active)}${formActions()}</form>`}</div>`).join('')}</div>`;}
 if(n==='verification'||n==='documents'){const docs=await api('/api/documents');let parents=[];if(n==='documents'){parents=(await api(state.env.area==='trade'?'/api/trade/listings?mine=1':'/api/caspian/shipments')).items;}
 const kinds=n==='verification'?['registration','certificate']:state.env.area==='trade'?['catalogue','certificate']:['invoice','packing_list','CMR','eCMR','TIR','eTIR','bill_of_lading','other'];return heading+`<p class="callout">${esc(t(n==='verification'?'verificationNote':'documentNote'))}</p><form class="panel" data-form="document"><div class="fields">${field('kind',kinds[0],{items:kinds})}${n==='documents'?field('parent_id',parents[0]?.id,{items:parents.map(p=>[p.id,p.title||p.reference])}):''}<label class="field wide"><span>${esc(t('file'))}</span><input name="file" type="file" accept="application/pdf,image/jpeg" required></label></div>${formActions('upload')}</form>${docRows(docs.items)}`;}
 if(n==='directory'){const r=await api('/api/directory?'+new URLSearchParams(state.filters));return heading+`<div class="directory-layout"><form class="panel filter-panel" data-form="search">${field('q',state.filters.q||'',{required:false})}${field('country',state.filters.country||'',{items:[['',t('all')],['BG','Bulgaria'],['CN','China']]})}${field('sector',state.filters.sector||'',{items:[['',t('all')],...state.env.taxonomy.sectors]})}${field('activity',state.filters.activity||'',{items:[['',t('all')],...state.env.taxonomy.activities]})}${field('employees',state.filters.employees||'',{items:[['',t('all')],'1-5','5-20','20-50','50-200','200+']})}${field('language',state.filters.language||'',{items:[['',t('all')],['bg','Български'],['en','English'],['zh','中文']]})}${formActions('search')}</form><div class="grid">${r.items.map(c=>`<div class="row"><h2>${esc(c.name_native)}</h2><p class="meta">${esc(c.name_latin)} · ${esc(c.address.city)} · ${esc(c.country)}</p><p>${esc(c.profile.description)}</p><p>${esc(c.profile.contact_name)} · ${esc(c.profile.phone)}<br>${esc(c.profile.contact_email)}</p>${tag(c.status)}</div>`).join('')||empty()}</div></div>`;}
 if(n==='listings'||n==='mine'){const params=new URLSearchParams({...state.filters,...(n==='mine'?{mine:'1'}:{})});const r=await api('/api/trade/listings?'+params);state.items=r.items;return heading+`${n==='mine'?btn('create','new-listing','','primary'):`<form class="toolbar" data-form="search">${field('q',state.filters.q||'',{required:false})}${field('country',state.filters.country||'',{items:[['',t('all')],['BG','Bulgaria'],['CN','China']]})}${field('direction',state.filters.direction||'',{items:[['',t('all')],'offer','wanted']})}${formActions('search')}</form>`}${r.visibility==='product_only'?`<p class="callout">${esc(t('productOnly'))}</p>`:''}<div class="rows">${r.items.map(r=>`<article class="row"><div class="row-top"><div><h2>${esc(r.title)}</h2><p class="meta">${esc(r.region)} · ${esc(r.country)} · ${esc(r.sector)}</p></div>${tag(r.status||r.direction)}</div>${r.description?`<p>${esc(r.description.slice(0,200))}</p>`:''}${r.company?`<p>${esc(r.company.name)} · ${esc(r.company.contact.phone)}</p>`:''}<div class="actions">${r.description?btn('details','listing-detail',`data-id="${r.id}"`):''}${n==='mine'?btn('edit','edit-listing',`data-id="${r.id}"`)+btn('remove','remove-listing',`data-id="${r.id}"`,'danger'):r.company && r.company_id!==state.user?.company_id?btn('inquiries','new-inquiry',`data-id="${r.id}"`):''}</div></article>`).join('')||empty()}</div>`;}
 if(n==='inquiries'){const r=await api('/api/trade/inquiries');return heading+`<div class="rows">${r.items.map(r=>`<div class="row"><div class="row-top"><h2>${esc(r.subject)}</h2>${tag(r.status)}</div><p>${esc(r.message)}</p>${btn('details','inquiry-detail',`data-id="${r.id}"`)}</div>`).join('')||empty()}</div>`;}
 if(n==='cargo'){const r=await api('/api/caspian/cargo');state.cargo=r.items;return heading+btn('create','new-cargo','','primary')+`<div class="rows">${r.items.map(r=>`<article class="row"><div class="row-top"><div><h2>${esc(r.reference)}</h2><p>${esc(r.origin_name)} · ${esc(r.destination_name)}</p></div>${tag(r.status)}</div><p class="meta">${r.weight_kg} kg · ${r.volume_m3} m³ · ${r.loading_m} LM · ${esc(r.pickup_date)}</p><p>${esc(r.description)}</p><div class="actions">${btn('routes','cargo-routes',`data-id="${r.id}"`)}${['draft','published'].includes(r.status)?btn('edit','edit-cargo',`data-id="${r.id}"`)+btn('remove','remove-cargo',`data-id="${r.id}"`,'danger'):''}</div></article>`).join('')||empty()}</div>`;}
 if(n==='routes'){state.cargo=(await api('/api/caspian/cargo')).items;return heading+`<p class="callout">${esc(t('routeNote'))}</p><form class="panel" data-form="route"><div class="fields">${field('cargo_id',state.selectedCargo||state.cargo[0]?.id,{items:state.cargo.map(c=>[c.id,c.reference])})}${field('scenario',state.scenario||'normal',{items:['normal','wind','congestion']})}${field('objective','balanced',{items:['balanced','cheapest','fastest']})}</div>${formActions('calculate')}</form><div id="route-results">${routeRows()}</div>`;}
 if(n==='matching'){state.cargo=(await api('/api/caspian/cargo')).items.filter(c=>['draft','published'].includes(c.status));return heading+`<p class="callout">${esc(t('matchingNote'))}</p><form class="panel" data-form="matching"><h2>${esc(t('selectCargo'))}</h2>${state.cargo.map(c=>`<label class="check"><input type="checkbox" name="cargo_ids" value="${c.id}">${esc(c.reference)} · ${esc(c.destination_name)} · ${c.weight_kg} kg / ${c.loading_m} LM</label>`).join('')||empty()}${formActions('preview')}</form><div id="matching-results"></div>`;}
 if(n==='shipments'){const r=await api('/api/caspian/shipments');state.items=r.items;return heading+`<div class="rows">${r.items.map(r=>`<div class="row"><div class="row-top"><div><h2>${esc(r.reference)}</h2><p>${esc(r.origin_name)} · ${esc(r.destination_name)}</p></div>${tag(r.status)}</div><p class="meta">${esc(t('estimated'))}: ${esc(new Date(r.eta).toLocaleString(lang==='zh'?'zh-CN':lang==='bg'?'bg-BG':'en-GB'))}</p>${btn('track','tracking',`data-id="${r.id}"`)} ${btn('addEvent','new-event',`data-id="${r.id}"`)}</div>`).join('')||empty()}</div>`;}
 if(n==='warehouses'){const [warehouses,shipments,reservations]=await Promise.all([api('/api/caspian/warehouses'),api('/api/caspian/shipments'),api('/api/caspian/reservations')]);return heading+`<div class="grid">${warehouses.items.map(w=>`<article class="row"><h2>${esc(w.name)}</h2><p>${esc(w.location)}</p><p>${w.capacity_m3} m³ · ${w.capacity_kg} kg</p><p>${w.daily_eur} EUR / ${esc(t('estimated'))}</p>${tag('draft')}</article>`).join('')}</div><div class="grid"><form class="panel" data-form="warehouse"><h2>${esc(t('create'))}</h2><div class="fields">${field('name')}${field('location','Poti',{items:['Poti','Batumi','Alat','Aktau']})}${field('capacity_m3',100,{type:'number'})}${field('capacity_kg',24000,{type:'number'})}${field('daily_eur',10,{type:'number'})}</div>${formActions()}</form><form class="panel" data-form="reservation"><h2>${esc(t('reserve'))}</h2><div class="fields">${field('warehouse_id','',{items:warehouses.items.map(w=>[w.id,w.name])})}${field('shipment_id','',{items:shipments.items.map(s=>[s.id,s.reference])})}${field('volume_m3',10,{type:'number'})}${field('weight_kg',1000,{type:'number'})}${field('starts_on','',{type:'date'})}${field('ends_on','',{type:'date'})}</div>${formActions()}</form></div><div class="rows">${reservations.items.map(r=>`<div class="row">${esc(warehouses.items.find(w=>w.id===r.warehouse_id)?.name)} · ${r.volume_m3} m³ · ${r.weight_kg} kg · ${esc(r.starts_on)} / ${esc(r.ends_on)}</div>`).join('')}</div>`;}
 if(n==='brokers'){
 const own=(await api('/api/caspian/broker-profile')).profile,canView=state.user.company_status==='verified';const profiles=canView?(await api('/api/caspian/brokers')).items:[];const inquiries=(await api('/api/caspian/broker-inquiries')).items;
 return heading+`<p class="callout">${esc(t('brokerNote'))}${canView?'':' '+esc(t('verification_required'))}</p><div class="grid">${profiles.map(b=>`<article class="row"><h2>${esc(b.company_name)}</h2><p>${esc(b.locations.join(', '))}</p><p>${esc(b.description)}</p><p>${esc(b.contact.phone)} · ${esc(b.contact.contact_email)}</p>${b.organization_id!==state.user.company_id?btn('requestBroker','request-broker',`data-id="${b.organization_id}"`):''}</article>`).join('')||empty()}</div><form class="panel" data-form="broker-profile" data-version="${own?.version||0}"><fieldset ${canView?'':'disabled'}><h2>${esc(t('broker_profile'))}</h2>${own?tag(own.status):''}<div class="fields">${field('license_reference',own?.license_reference)}${field('description',own?.description,{type:'textarea'})}<fieldset><legend>${esc(t('locations'))}</legend>${['Poti','Batumi','Alat','Tbilisi','Almaty','Aktau'].map(l=>`<label class="check"><input type="checkbox" name="locations" value="${l}" ${own?.locations.includes(l)?'checked':''}>${l}</label>`).join('')}</fieldset><fieldset><legend>${esc(t('services'))}</legend>${['customs','documentation','transit'].map(l=>`<label class="check"><input type="checkbox" name="services" value="${l}" ${own?.services.includes(l)?'checked':''}>${esc(t(l))}</label>`).join('')}</fieldset></div>${check('publish_consent')}${formActions()}</fieldset></form><h2>${esc(t('broker_inquiries'))}</h2><div class="rows">${inquiries.map(i=>`<article class="row">${tag(i.status)}<p>${esc(i.message)}</p>${i.recipient_id===state.user.company_id?btn('accept','broker-status',`data-id="${i.id}" data-status="accepted"`)+btn('reject','broker-status',`data-id="${i.id}" data-status="rejected"`):''}${btn('closed','broker-status',`data-id="${i.id}" data-status="closed"`)}</article>`).join('')||empty()}</div>`;
 }
 if(n==='brokers_admin'){state.items=(await api('/api/admin/brokers')).items;return heading+`<div class="rows">${state.items.map(b=>`<article class="row"><h2>${esc(b.company_name||b.organization_id)}</h2>${tag(b.status)}<p>${esc(b.description)}</p><p>${esc(b.license_reference)}</p>${btn('review','review-broker',`data-id="${b.organization_id}"`)}</article>`).join('')||empty()}</div>`;}
 if(n==='integrations'){const r=await api('/api/caspian/capabilities');return heading+`<p class="callout">${esc(t('integrationNote'))}</p><div class="grid">${r.integrations.map(i=>`<div class="row"><h2>${esc(i.id.toUpperCase())}</h2>${tag('unavailable')}<p>${esc(t('integrationNote'))}</p></div>`).join('')}</div>`;}
 if(n==='admin'){state.items=(await api('/api/admin/companies')).items;return heading+`<div class="rows">${state.items.map(c=>`<div class="row"><div class="row-top"><div><h2>${esc(c.name_native)}</h2><p class="meta">${esc(c.country)} · ${esc(c.registration_number)}</p></div>${tag(c.status)}</div><p>${esc(c.review_note)}</p>${btn('review','review-company',`data-id="${c.id}"`)}</div>`).join('')||empty()}</div>`;}
 if(n==='audit'){const r=await api('/api/admin/audit');return heading+`<div class="rows">${r.items.map(a=>`<div class="row"><h3>${esc(a.action)}</h3><p class="meta">${esc(new Date(a.created_at).toLocaleString())}</p><p>${esc(a.entity_id)}</p><p>${esc(a.details.note||'')}</p></div>`).join('')||empty()}</div>`;}
 return heading+empty();
}
function docRows(items,review=false){return `<div class="rows">${items.map(d=>`<div class="row"><div class="row-top"><div><h3>${esc(d.name)}</h3><p class="meta">${esc(t(d.kind))} · ${Math.ceil(d.size/1024)} KB</p></div>${tag(d.status)}</div><p>${esc(d.review_note)}</p>${btn('download','download',`data-id="${d.id}"`)}${state.env.area==='trade'&&d.company_id===state.user?.company_id&&d.status==='reviewed'?btn(d.visibility==='registered'?'privateAccess':'registeredAccess','document-visibility',`data-id="${d.id}" data-visibility="${d.visibility==='registered'?'company':'registered'}"`):''}${review?btn('saveReview','review-document',`data-id="${d.id}"`):''}</div>`).join('')||empty()}</div>`;}
function listingForm(r={}){return `<h2>${esc(t(r.id?'edit':'create'))}</h2><form data-form="listing" data-id="${esc(r.id||'')}"><div class="fields">${field('title',r.title,{wide:true})}${field('direction',r.direction||'offer',{items:['offer','wanted']})}${field('partnership',r.partnership||'export',{items:['export','import','distribution','logistics','investment']})}${field('description',r.description,{type:'textarea',wide:true})}${field('sector',r.sector)}${field('country',r.country||'BG',{items:[['BG','Bulgaria'],['CN','China']]})}${field('region',r.region)}${field('language',r.language||lang,{items:['bg','en','zh']})}${field('expires_on',r.expires_on?.slice(0,10),{type:'date'})}${field('status',r.status||'draft',{items:['draft','published','closed']})}${field('currency',r.details?.currency||'EUR',{items:['EUR','USD']})}${['price_min','price_max','moq'].map(k=>field(k,r.details?.[k]??'',{type:'number',required:false})).join('')}${field('incoterms',r.details?.incoterms||'EXW',{items:['EXW','FCA','FOB','CIF','DAP','DDP']})}${field('payment',r.details?.payment,{required:false})}${field('certificates',r.details?.certificates,{required:false})}${field('references',r.details?.references,{required:false})}</div>${formActions()}</form>`;}
function cargoForm(r={}){return `<h2>${esc(t(r.id?'edit':'create'))}</h2><form data-form="cargo" data-id="${esc(r.id||'')}"><div class="fields">${field('reference',r.reference)}${field('origin_name',r.origin_name||'Plovdiv',{items:['Plovdiv','Varna']})}${field('destination_name',r.destination_name||'Almaty',{items:['Almaty','Aktau','Turkmenbashi']})}${['weight_kg','volume_m3','loading_m','pallets'].map(k=>field(k,r[k]??({weight_kg:1000,volume_m3:5,loading_m:1.2,pallets:2}[k]),{type:'number'})).join('')}${field('pickup_date',r.pickup_date||new Date().toISOString().slice(0,10),{type:'date'})}${field('temperature',r.temperature||'ambient',{items:['ambient','chilled']})}${field('description',r.description,{type:'textarea',wide:true})}</div>${check('hazardous',r.hazardous)}${check('synthetic',true)}${formActions()}</form>`;}
function routeRows(){return `<div class="rows">${state.routes.map(r=>`<article class="row"><div class="row-top"><div><div class="price">${r.estimated_eur.toLocaleString()} EUR</div><p>${r.range_hours.join('–')} ${esc(t('hours'))} · ${r.transfers} ${esc(t('transfers'))}</p></div>${tag('estimated')}</div><div class="steps">${r.stages.map(s=>`<span>${esc(s.from)} · ${esc(t(s.mode))} · ${esc(s.to)}</span>`).join('')}</div><p class="meta">${r.stages.map(s=>`${esc(s.to)}: ${s.wait_hours} ${esc(t('hours'))} ${esc(t('wait'))}`).join(' · ')}</p>${btn('planShipment','plan-shipment',`data-id="${r.id}"`)}</article>`).join('')||(state.calculated?`<div class="callout">${esc(t('noRoute'))}</div>`:'')}</div>`;}
async function action(button){const a=button.dataset.action,r=state.items.find(r=>r.id===button.dataset.id),c=state.cargo.find(c=>c.id===button.dataset.id);
 if(a==='nav'){state.nav=button.dataset.nav;state.filters={};state.draft=null;await render();}
 else if(a==='auth'){state.auth='login';state.nav='overview';await render();}
 else if(a==='auth-mode'){state.auth=button.dataset.mode;state.draft=null;await render();}
 else if(a==='refresh')await render();
 else if(a==='logout'){await api('/api/auth/logout','POST',{});await refreshMe();state.nav='overview';await render();}
 else if(a==='new-listing'||a==='edit-listing')modal(listingForm(r));
 else if(a==='remove-listing'){if(confirm(t('confirmRemove'))){await api('/api/trade/listings/'+r.id,'DELETE',{version:r.version});await render();}}
 else if(a==='listing-detail'){const docs=await api('/api/documents?listing_id='+r.id);modal(`<h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><p>${esc(r.company?.name||'')}</p><p>${esc(r.company?.contact?.phone||'')}<br>${esc(r.company?.contact?.contact_email||'')}</p><p>${esc(r.details?.certificates||'')} · ${esc(r.details?.incoterms||'')}</p><p>${esc(r.details?.price_min??'')} – ${esc(r.details?.price_max??'')} ${esc(r.details?.currency||'')}</p><h3>${esc(t('documents'))}</h3>${docRows(docs.items)}`);}
 else if(a==='new-inquiry')modal(`<h2>${esc(t('inquiries'))}</h2><form data-form="inquiry" data-id="${r.id}"><div class="fields">${field('subject',r.title,{wide:true})}${field('message','',{type:'textarea',wide:true})}</div>${formActions('send')}</form>`);
 else if(a==='inquiry-detail'){const i=await api('/api/trade/inquiries/'+button.dataset.id);modal(`<h2>${esc(i.subject)}</h2><p>${esc(i.message)}</p><ul class="timeline">${i.messages.map(m=>`<li><p>${esc(m.body)}</p><time>${esc(new Date(m.created_at).toLocaleString())}</time></li>`).join('')}</ul><form data-form="reply" data-id="${i.id}">${field('message','',{type:'textarea'})}${formActions('reply')}</form>`);}
 else if(a==='request-broker')modal(`<h2>${esc(t('requestBroker'))}</h2><form data-form="broker-inquiry" data-id="${button.dataset.id}">${field('message','',{type:'textarea'})}${formActions('send')}</form>`);
 else if(a==='broker-status'){await api('/api/caspian/broker-inquiries/'+button.dataset.id,'PATCH',{status:button.dataset.status});await render();}
 else if(a==='review-broker'){const b=state.items.find(x=>x.organization_id===button.dataset.id);state.reviewBroker=b;const docs=await api('/api/documents?company_id='+b.organization_id);modal(`<h2>${esc(t('review'))}</h2>${docRows(docs.items,true)}<form data-form="broker-review" data-id="${b.organization_id}">${field('status','approved',{items:['approved','suspended']})}${field('note','',{type:'textarea'})}${formActions()}</form>`);}
 else if(a==='new-cargo'||a==='edit-cargo')modal(cargoForm(c));
 else if(a==='remove-cargo'){if(confirm(t('confirmRemove'))){await api('/api/caspian/cargo/'+c.id,'DELETE',{version:c.version});await render();}}
 else if(a==='cargo-routes'){state.selectedCargo=c.id;state.nav='routes';state.routes=[];await render();}
 else if(a==='plan-shipment')modal(`<h2>${esc(t('planShipment'))}</h2><p class="callout">${esc(t('routeNote'))}</p><form data-form="shipment" data-id="${button.dataset.id}">${field('reference')}${formActions()}</form>`);
 else if(a==='commit-matching'){const result=await api('/api/caspian/matching','POST',{cargo_ids:state.matchIds,commit:true});notice(t('success'));await render();}
 else if(a==='tracking'){const s=await api('/api/caspian/shipments/'+button.dataset.id);modal(`<h2>${esc(s.reference)}</h2>${tag(s.status)}<p class="callout">${esc(t('routeNote'))}</p><ul class="timeline">${s.events.map(e=>`<li><h3>${esc(t(e.event_type))}</h3><p>${esc(e.location_name)} · ${esc(t(e.transport_mode))}</p><time>${esc(new Date(e.observed_at).toLocaleString())}</time><p>${esc(e.note)}</p></li>`).join('')||empty()}</ul><h3>${esc(t('documents'))}</h3>${s.checklist.map(d=>`<p>${esc(d.kind)} · ${d.present?'✓':'—'}</p>`).join('')}${btn('exportData','export-shipment',`data-id="${s.id}"`,'primary')}`);}
 else if(a==='export-shipment'){const s=await api('/api/caspian/shipments/'+button.dataset.id+'/export');downloadBlob(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),s.reference+'.json');}
 else if(a==='new-event'){const cap=await api('/api/caspian/capabilities');modal(`<h2>${esc(t('addEvent'))}</h2><form data-form="event" data-id="${button.dataset.id}"><div class="fields">${field('source_event_id',crypto.randomUUID())}${field('event_type','terminal_in',{items:cap.event_types})}${field('location_name')}${field('transport_mode','terminal',{items:cap.event_modes})}${field('observed_at',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),{type:'datetime-local'})}${field('note','',{type:'textarea',required:false,wide:true})}</div>${formActions()}</form>`);}
 else if(a==='download'){const r=await fetch('/api/documents/'+button.dataset.id,{credentials:'same-origin'});if(!r.ok)throw new Error(t('error'));downloadBlob(await r.blob(),'document');}
 else if(a==='document-visibility'){await api('/api/documents/'+button.dataset.id,'PATCH',{visibility:button.dataset.visibility});await render();}
 else if(a==='review-company'){state.reviewCompany=r;const docs=await api('/api/documents?company_id='+r.id);modal(`<h2>${esc(r.name_native)}</h2>${tag(r.status)}<p class="callout">${esc(t('verificationNote'))}</p>${docRows(docs.items,true)}<form data-form="company-review" data-id="${r.id}">${field('status','verified',{items:['verified','rejected','suspended']})}${field('note','',{type:'textarea'})}${formActions('save')}</form>`);}
 else if(a==='review-document')modal(`<h2>${esc(t('review'))}</h2><form data-form="doc-review" data-id="${button.dataset.id}">${field('status','reviewed',{items:['reviewed','rejected']})}${field('note','',{type:'textarea'})}${formActions()}</form>`);
}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();b.disabled=true;action(b).catch(e=>notice(words[e.code]?t(e.code):t('error'),true)).finally(()=>b.disabled=false);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();document.body.dataset.saving='1';app.setAttribute('aria-busy','true');const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);const kind=form.dataset.form,b=kind==='register'||kind==='profile'?companyBody(form):object(form);try{
 if(kind==='login'||kind==='register'||kind==='accept'){await api('/api/auth/'+(kind==='accept'?'accept-invitation':kind),'POST',b);await refreshMe();state.nav='overview';}
 else if(kind==='password'){await api('/api/auth/password','POST',b);}
 else if(kind==='profile')await api('/api/company','PUT',{...b,version:state.company.version});
 else if(kind==='invite'){const r=await api('/api/company/invitations','POST',b);modal(`<h2>${esc(t('invitation'))}</h2><p>${esc(t('manualInvite'))}</p><pre>${esc(r.invitation)}</pre>`);return;}
 else if(kind==='member')await api('/api/company/members/'+form.dataset.id,'PATCH',b);
 else if(kind==='search'){state.filters=b;}
 else if(kind==='listing'){const r=state.items.find(x=>x.id===form.dataset.id);await api('/api/trade/listings'+(r?'/'+r.id:''),r?'PUT':'POST',{...b,...(r?{version:r.version}:{})});detail.close();}
 else if(kind==='inquiry'){await api('/api/trade/inquiries','POST',{...b,listing_id:form.dataset.id});detail.close();}
 else if(kind==='reply'){await api('/api/trade/inquiries/'+form.dataset.id+'/messages','POST',b);detail.close();}
 else if(kind==='cargo'){const r=state.cargo.find(x=>x.id===form.dataset.id);await api('/api/caspian/cargo'+(r?'/'+r.id:''),r?'PUT':'POST',{...b,...(r?{version:r.version}:{})});detail.close();}
 else if(kind==='route'){const r=await api('/api/caspian/routes','POST',b);state.routes=r.items;state.scenario=b.scenario;state.selectedCargo=b.cargo_id;state.calculated=true;document.querySelector('#route-results').innerHTML=routeRows();return;}
 else if(kind==='shipment'){await api('/api/caspian/shipments','POST',{...b,route_id:form.dataset.id,cargo_id:state.selectedCargo,scenario:state.scenario||'normal'});detail.close();state.nav='shipments';}
 else if(kind==='event'){await api('/api/caspian/shipments/'+form.dataset.id+'/events','POST',{...b,observed_at:new Date(b.observed_at).toISOString()});detail.close();}
 else if(kind==='matching'){state.matchIds=new FormData(form).getAll('cargo_ids');const r=await api('/api/caspian/matching','POST',{cargo_ids:state.matchIds,commit:false});document.querySelector('#matching-results').innerHTML=`<div class="grid">${r.groups.map(g=>`<div class="row"><h2>${esc(g.origin)} · ${esc(g.destination)}</h2><p>${g.cargo_ids.length} · ${g.weight_kg} kg · ${g.volume_m3} m³ · ${g.loading_m} LM</p><p>${esc(t('utilization'))}: ${Math.round(g.utilization*100)}%</p></div>`).join('')}</div>${btn('commit','commit-matching','','primary')}`;return;}
 else if(kind==='document'){const file=form.elements.file.files[0];if(!file||file.size>5242880)throw new Error(t('error'));const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await api('/api/documents','POST',{kind:b.kind,parent_id:b.parent_id,name:file.name,content_base64:btoa(binary)});}
 else if(kind==='company-review'){await api('/api/admin/companies/'+form.dataset.id+'/review','POST',{...b,version:state.reviewCompany.version});detail.close();}
 else if(kind==='doc-review'){await api('/api/documents/'+form.dataset.id+'/review','POST',b);detail.close();}
 else if(kind==='broker-profile'){const f=new FormData(form);await api('/api/caspian/broker-profile','PUT',{...b,locations:f.getAll('locations'),services:f.getAll('services'),version:Number(form.dataset.version)});}
 else if(kind==='broker-inquiry'){await api('/api/caspian/broker-inquiries','POST',{...b,recipient_id:form.dataset.id});detail.close();}
 else if(kind==='broker-review'){await api('/api/admin/brokers/'+form.dataset.id,'POST',{...b,version:state.reviewBroker.version});detail.close();}
 else if(kind==='warehouse')await api('/api/caspian/warehouses','POST',b);
 else if(kind==='reservation')await api('/api/caspian/reservations','POST',b);
 notice(t('success'));await refreshMe();await render();
 }catch(err){const message=words[err.code]?t(err.code):t('error');const target=form.querySelector('.error-text');if(target)target.textContent=message;notice(message,true);}finally{buttons.forEach(b=>b.disabled=false);delete document.body.dataset.saving;app.removeAttribute('aria-busy');}});
try{state.env=await api('/api/environment');await refreshMe();state.nav=state.env.area==='trade'&&!state.user?'listings':'overview';document.documentElement.lang=lang;await render();}catch{app.innerHTML='<main><h1>INTERNATIONAL BUSINESS HUB</h1><p>Service unavailable / Услугата не е достъпна / 服务不可用</p></main>';}
